class Solution{struct N{N*c[26]{};string w;};public:vector<string>findWords(vector<vector<char>>&b,vector<string>&ws){N*r=new N;for(auto&s:ws){N*x=r;for(char c:s)x=x->c[c-'a']?x->c[c-'a']:(x->c[c-'a']=new N);x->w=s;}vector<string>o;function<void(int,int,N*)>f=[&](int i,int j,N*x){char c=b[i][j];N*y=x->c[c-'a'];if(!y)return;if(!y->w.empty()){o.push_back(y->w);y->w.clear();}b[i][j]='#';for(auto d:vector<pair<int,int>>{{1,0},{-1,0},{0,1},{0,-1}}){int u=i+d.first,v=j+d.second;if(u>=0&&v>=0&&u<b.size()&&v<b[0].size()&&b[u][v]!='#')f(u,v,y);}b[i][j]=c;};for(int i=0;i<b.size();i++)for(int j=0;j<b[0].size();j++)f(i,j,r);return o;}};
